#!/usr/bin/env Rscript
# =====================================================================
# Cross-crop figures + summary table for the dominance-identifiability study.
# Reads per-dataset *_ortho.csv / *_diagnostics.csv / *_null.csv (uniform generic
# format) plus the original alfalfa/potato results, and emits:
#   - tables/cross_crop_summary.csv      (cross-crop summary; read by make_fig_crosscrop.R)
# The figures are now generated by dedicated ggplot scripts on the shared theme:
# make_fig_crosscrop.R, make_fig_ncurve.R (experiments/empirical/multi/) and
# make_fig_regime.R (experiments/simulations/poly_ortho/).
# NA-tolerant: datasets whose files are absent are skipped; missing fields plot blank.
# Run from repo root (paths are relative).
# =====================================================================
FIG <- "paper/figures"; dir.create(FIG, showWarnings = FALSE, recursive = TRUE)
TAB <- "tables"; dir.create(TAB, showWarnings = FALSE, recursive = TRUE)
rd <- function(p) if (!is.null(p) && length(p)==1 && !is.na(p) && nzchar(p) && file.exists(p)) read.csv(p, check.names = FALSE) else NULL

# dataset config: label, clade, n, files, and column name for the standard Vd-share
cfg <- list(
  list(name="alfalfa",     label="Alfalfa",        clade="legume",  n=424,
       ortho="experiments/empirical/multi/out/alfalfa_ortho.csv", vdcol="std_Vd", trait="yi_year",
       diag="experiments/empirical/multi/out/alfalfa_diagnostics.csv", null="experiments/empirical/multi/out/alfalfa_null.csv", effrank=NA),
  list(name="potato",      label="Potato SolCAP",  clade="vegetable", n=187,
       ortho="experiments/empirical/multi/out/potato_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/potato_diagnostics.csv", null="experiments/empirical/multi/out/potato_null.csv", effrank=NA),
  list(name="blueberry",   label="Blueberry UF-GP",   clade="fruit",   n=1804,
       ortho="experiments/empirical/multi/out/blueberry_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/blueberry_diagnostics.csv", null="experiments/empirical/multi/out/blueberry_null.csv", effrank=NA),
  list(name="blueberry2",  label="Blueberry UF-fruit",   clade="fruit",   n=1559,
       ortho="experiments/empirical/multi/out/blueberry2_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/blueberry2_diagnostics.csv", null="experiments/empirical/multi/out/blueberry2_null.csv", effrank=NA),
  list(name="potato2",     label="Potato SLU",     clade="vegetable", n=669,
       ortho="experiments/empirical/multi/out/potato2_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/potato2_diagnostics.csv", null="experiments/empirical/multi/out/potato2_null.csv", effrank=NA),
  list(name="panicum",     label="Panicum (grass)", clade="grass",  n=530,
       ortho="experiments/empirical/multi/out/panicum_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/panicum_diagnostics.csv", null="experiments/empirical/multi/out/panicum_null.csv", effrank=NA),
  list(name="rose",        label="Rose",           clade="ornamental", n=106,
       ortho="experiments/empirical/multi/out/rose_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/rose_diagnostics.csv", null="experiments/empirical/multi/out/rose_null.csv", effrank=NA),
  # n = 197: the tetraploid-called panel (IDB-4829913 updog discrete, 226 accessions
  # genotyped at ploidy 4) intersected with the 3 LS-mean traits shipped with it.
  # The previous n=590 was the mixed-ploidy IDB-6439486 panel; see
  # experiments/data_preparation/build_miscanthus.R.
  list(name="miscanthus",  label="Miscanthus (grass)", clade="grass", n=197,
       ortho="experiments/empirical/multi/out/miscanthus_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/miscanthus_diagnostics.csv", null="experiments/empirical/multi/out/miscanthus_null.csv", effrank=NA),
  list(name="blueberry_gc", label="BB-UF-call",  clade="fruit",   n=1804,
       ortho="experiments/empirical/multi/out/blueberry_gc_ortho.csv", vdcol="std_Vd",
       diag="experiments/empirical/multi/out/blueberry_gc_diagnostics.csv", null="experiments/empirical/multi/out/blueberry_gc_null.csv", effrank=NA)
)

S <- data.frame()
for (d in cfg) {
  o <- rd(d$ortho); if (is.null(o)) next
  # alfalfa's three "traits" are temporal aggregations of one biomass-yield trait
  # (pairwise r >= 0.92); use the overall yi_year slice as the single representative.
  if (!is.null(d$trait) && "trait" %in% names(o)) o <- o[o$trait == d$trait, , drop = FALSE]
  vd <- mean(o[[d$vdcol]], na.rm = TRUE)
  vd_lo <- min(o[[d$vdcol]], na.rm = TRUE); vd_hi <- max(o[[d$vdcol]], na.rm = TRUE)
  nperm <- rd(d$null); permv <- if (!is.null(nperm) && "std_Vd" %in% names(nperm)) mean(nperm$std_Vd, na.rm = TRUE) else NA
  dg <- rd(d$diag); er <- if (!is.null(dg) && "eff_rank" %in% names(dg)) dg$eff_rank[1] else d$effrank
  adc <- if (!is.null(dg) && "AD" %in% names(dg)) dg$AD[1] else NA
  # orthogonal A+D2+D3+D4 decomposition: trait-averaged posterior-mean degree fractions
  # (averaged over the same trait rows used for std_Vd above). These show whether fitted
  # non-additive variance localizes to D2 or spreads across D2/D3/D4.
  om <- function(col) if (col %in% names(o)) mean(o[[col]], na.rm = TRUE) else NA
  oa <- om("A"); od2 <- om("D2"); od3 <- om("D3"); od4 <- om("D4")
  S <- rbind(S, data.frame(name=d$name, label=d$label, clade=d$clade, n=d$n, n_traits=nrow(o),
                           std_Vd=round(vd,3), std_Vd_trait_min=round(vd_lo,3), std_Vd_trait_max=round(vd_hi,3),
                           perm_null=round(permv,3), eff_rank=round(er,3), AD_cos=round(adc,3),
                           ortho_A=round(oa,3), ortho_D2=round(od2,3), ortho_D3=round(od3,3), ortho_D4=round(od4,3),
                           ortho_D2_lo=round(om("D2_lo"),3), ortho_D2_hi=round(om("D2_hi"),3),
                           ortho_D3_lo=round(om("D3_lo"),3), ortho_D3_hi=round(om("D3_hi"),3),
                           ortho_D4_lo=round(om("D4_lo"),3), ortho_D4_hi=round(om("D4_hi"),3)))
}
write.csv(S, file.path(TAB, "cross_crop_summary.csv"), row.names = FALSE)
cat("cross_crop_summary.csv:\n"); print(S)

## All cross-crop figures now have dedicated ggplot generators on the shared theme:
##   fig_crosscrop -> experiments/empirical/multi/make_fig_crosscrop.R   (reads the table above)
##   fig_ncurve    -> experiments/empirical/multi/make_fig_ncurve.R
##   fig_regime    -> experiments/simulations/poly_ortho/make_fig_regime.R
## This script now only builds the cross-crop summary table.
cat("SUMMARY TABLE DONE\n")
